#!/usr/bin/env node
"use strict";

// The native writer behind `callum-flow-event --type` (cbundy/dev-system#792): builds one envelope-v1
// event from a type and a payload, checked at run time against the image's shapes file
// (factory-event-shapes.json, generated by scripts/build-event-docs.js from docs/factory-events/schemas/).
// Permanent, unlike factory-event-translate.js, which goes with the old log.
//
// Run time checks only what the reader needs (docs/factory-events/README.md, "The writer never
// refuses what a newer caller may know"): the type, the options, and for a type and version in the
// shapes, that every required field is present and every field the schema has carries its JSON type
// (the same check as readEvent in plugins/factory-loop/hooks/v2/event-reader.ts). Enum values, bounds
// and unknown fields are checked in `npm test` only. An unknown type or version is written with a warning.
//
// CLI: node factory-event-write.js --type T [--type-version N] --data JSON [--issue N] --repo O/N
//   --device D --actor A [--session-id S] [--regime R] [--event-id UUID] [--snapshot JSON] [--ts ISO]
// Prints the event as one JSON line on stdout and warnings on stderr. Exit 2 on a refusal (one
// `callum-flow-event:` line on stderr, nothing on stdout), 1 on a crash.

const fs = require("node:fs");
const path = require("node:path");
const crypto = require("node:crypto");

const PREFIX = "callum-flow-event:";
const TYPE_RE = /^[a-z][a-z_]*$/;
const POSITIVE_INT_RE = /^[1-9][0-9]*$/;
const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;

class UsageError extends Error {}

const isObj = (v) => v !== null && typeof v === "object" && !Array.isArray(v);
const jsonTypeOf = (v) => (v === null ? "null" : Array.isArray(v) ? "array" : typeof v);

// Mirrors matchesType in event-reader.ts.
function matchesType(want, v) {
  if (want === "integer") return typeof v === "number" && Number.isInteger(v);
  if (want === "number") return typeof v === "number" && Number.isFinite(v);
  return jsonTypeOf(v) === want;
}

const wantedTypes = (s) => (s.type === undefined ? [] : Array.isArray(s.type) ? s.type : [s.type]);

// The first problem with data against a shape, as "field X ..." text, or null.
function checkData(shape, data) {
  for (const r of shape.required || []) {
    if (!(r in data) || data[r] === undefined) return `field ${r} is missing`;
  }
  for (const [name, sub] of Object.entries(shape.properties || {})) {
    const want = wantedTypes(sub);
    if (name in data && want.length > 0 && !want.some((t) => matchesType(t, data[name]))) {
      return `field ${name} must be ${want.join(" or ")}, got ${jsonTypeOf(data[name])}`;
    }
  }
  return null;
}

function positiveInt(name, text) {
  if (typeof text !== "string" || !POSITIVE_INT_RE.test(text)) throw new UsageError(`${name} must be a positive integer`);
  return Number(text);
}

function pickVersion(snapshot, key) {
  let snap = null;
  try {
    snap = JSON.parse(snapshot || "null");
  } catch {
    snap = null;
  }
  return isObj(snap) && typeof snap[key] === "string" ? snap[key] : null;
}

// input: { type, typeVersion?, data (JSON text), issue?, repo, device, actor, sessionId?, eventId?,
// snapshot?, ts? } (strings as given on the command line). shapes: { current, schemas } or null.
// Returns { event, warnings }; throws UsageError on a refusal.
function buildEvent(input, shapes) {
  const { type } = input;
  if (typeof type !== "string" || !TYPE_RE.test(type)) throw new UsageError(`--type must match ${TYPE_RE.source}`);
  let data;
  try {
    data = JSON.parse(input.data);
  } catch {
    throw new UsageError(`${type}: --data is not JSON`);
  }
  if (!isObj(data)) throw new UsageError(`${type}: --data must be a JSON object, got ${jsonTypeOf(data)}`);
  const issue = input.issue === undefined ? null : positiveInt("--issue", input.issue);
  const given = input.typeVersion === undefined ? null : positiveInt("--type-version", input.typeVersion);

  const warnings = [];
  let version = given;
  if (shapes === null || shapes === undefined) {
    version = version === null ? 1 : version;
  } else {
    const known = shapes.current && shapes.current[type];
    if (version === null) version = known === undefined ? 1 : known;
    const shape = shapes.schemas && shapes.schemas[`${type}.v${version}`];
    if (shape === undefined) {
      warnings.push(`warning: unknown factory event: ${type} v${version} - written unchecked`);
    } else {
      const problem = checkData(shape, data);
      if (problem !== null) throw new UsageError(`${type} v${version}: ${problem}`);
      if (shape["x-issue"] === "required" && issue === null) throw new UsageError(`${type} v${version}: --issue is required`);
    }
  }

  // The regime is written as given and never refused; a value the shapes' enum lacks only warns.
  const regime = input.regime ? input.regime : null;
  if (regime !== null && shapes && shapes.schemas) {
    const spec = shapes.schemas["envelope.v1"] && shapes.schemas["envelope.v1"].properties && shapes.schemas["envelope.v1"].properties.regime;
    if (spec && Array.isArray(spec.enum) && !spec.enum.includes(regime)) {
      warnings.push(`warning: unknown regime '${regime}' - written as given`);
    }
  }

  const eventId = UUID_RE.test(input.eventId || "") ? input.eventId : crypto.randomUUID();
  const snap = input.snapshot || "";
  const event = {
    envelope: 1,
    event_id: eventId,
    ts: input.ts || new Date().toISOString(),
    type,
    type_version: version,
    repo: input.repo,
    device: input.device,
    actor: input.actor,
    session_id: input.sessionId ? input.sessionId : null,
    issue,
    base_image: pickVersion(snap, "base_image"),
    dev_image: pickVersion(snap, "dev_image"),
    template_version: pickVersion(snap, "template_version"),
    plugin_version: pickVersion(snap, "plugin_version"),
    regime,
    data,
  };
  return { event, warnings };
}

// The shapes file: CALLUM_EVENT_SHAPES, else next to this script, else the share dir. Null (and a
// warning) when it cannot be read.
function loadShapes(env, warnings) {
  const share = env.DEV_SYSTEM_SHARE || "/usr/local/share/dev-system";
  const candidates = env.CALLUM_EVENT_SHAPES
    ? [env.CALLUM_EVENT_SHAPES]
    : [path.join(__dirname, "factory-event-shapes.json"), path.join(share, "factory-event-shapes.json")];
  for (const p of candidates) {
    try {
      const shapes = JSON.parse(fs.readFileSync(p, "utf-8"));
      if (isObj(shapes) && isObj(shapes.schemas) && isObj(shapes.current)) return shapes;
    } catch {
      // try the next place
    }
  }
  warnings.push(`warning: factory-event-shapes.json not readable (${candidates[0]}) - written unchecked`);
  return null;
}

const OPTIONS = {
  "--type": "type", "--type-version": "typeVersion", "--data": "data", "--issue": "issue", "--repo": "repo",
  "--device": "device", "--actor": "actor", "--session-id": "sessionId", "--regime": "regime", "--event-id": "eventId",
  "--snapshot": "snapshot", "--ts": "ts",
};

function main(argv, env) {
  const input = {};
  for (let i = 0; i < argv.length; i += 2) {
    const key = OPTIONS[argv[i]];
    if (key === undefined || i + 1 >= argv.length) throw new UsageError(`unknown or incomplete option '${argv[i]}'`);
    input[key] = argv[i + 1];
  }
  if (input.data === undefined) throw new UsageError("--data is required");
  const loadWarnings = [];
  const shapes = loadShapes(env, loadWarnings);
  const { event, warnings } = buildEvent(input, shapes);
  return { line: JSON.stringify(event), warnings: [...loadWarnings, ...warnings] };
}

if (require.main === module) {
  try {
    const { line, warnings } = main(process.argv.slice(2), process.env);
    for (const w of warnings) process.stderr.write(`${PREFIX} ${w}\n`);
    process.stdout.write(`${line}\n`);
  } catch (err) {
    if (err instanceof UsageError) {
      process.stderr.write(`${PREFIX} ${err.message}\n`);
      process.exit(2);
    }
    process.stderr.write(`${PREFIX} ${err.message}\n`);
    process.exit(1);
  }
}

module.exports = { buildEvent, checkData, UsageError };
